def f(g):
    H,W=len(g),len(g[0])
    bg=Counter(x for r in g for x in r).most_common(1)[0][0]
    cur=[r[:] for r in g]
    changed=True
    while changed:
        changed=False
        # gather comps of current cur
        cs=comps(cur,bg)
        # candidates that can shift right (fit & dest free of other colors)
        move=[]
        for c,pts in cs:
            if max(x for _,x in pts)+1>=W: continue
            can=True
            for y,x in pts:
                n=x+1
                if n>=W or cur[y][n]!=bg and (y,n) not in pts:
                    can=False;break
            if can: move.append((c,pts))
        if not move: break
        # process: moves that don't block others first
        for c,pts in sorted(move,key=lambda t:-len(t[1])):
            for y,x in pts: cur[y][x]=bg
            for y,x in pts: cur[y][x+1]=c
            changed=True
        for c,pts in cs:
            if cur[min(y for y,_ in pts)][min(x for _,x in pts)]!=c: pass
        # leftover comps that couldn't move get restored
        for c,pts in cs:
            placed=False
            for m in move:
                if m[0]==c and pts==m[1]: placed=True
            if not placed:
                for y,x in pts: cur[y][x]=c
    return cur
