def solve(g, mode='min'):
    bg=g[0][0]; H=len(g);W=len(g[0])
    # components 4-conn
    cs=comps4(g,bg)
    dest={}
    for c,p in cs:
        d={(y,x+1) for y,x in p}
        dest[c]=d
    o=[[bg]*W for _ in range(H)]
    for (y,x) in [(a,b) for a in range(H) for b in range(W)]:
        cols=[c for c,d in dest.items() if (y,x) in d]
        if cols:
            if len(cols)>1:
                # pick: shape whose min source x is max/min/bottom-most/top-most
                sources=[(min(x for _,xx in dest[c]), max(y for yy,xx in dest[c])) for c in cols]
                if mode=='max': sources.sort(key=lambda s:-s[0]); c=sources[0][0]
                elif mode=='min': sources.sort(key=lambda s:s[0]); c=sources[0][0]
                else: sources.sort(reverse=True); c=sources[0][0]
                o[y][x]=g[next(iter(p for p in []))[0]] if False else g[[cv for cv in cols].__iter__().__next__() ]
            else:
                o[y][x]=list(dest.__dict__)
    return o
